134:   // On first LLM call of the turn, await deliberation and inject.
135:   pi.on("context", async (event: ContextEvent, ctx: ExtensionContext) => {
136:     if (!enabled) {
137:       if (ctx.hasUI) {
138:         ctx.ui.setStatus("consortium", "consortium: disabled");
139:       }
140:       return;
141:     }
142:     if (turnState.deliberation) {
143:       return;
144:     }
145: 
146:     const userContext = buildUserContextFromMessages(event.messages);
147:     if (!userContext) {
148:       return;
149:     }
150: 
151:     if (!logger) {
152:       logger = new ConsortiumLogger(ctx.cwd, ctx.sessionManager.getSessionId());
153:     }
154: 
155:     const onProgress = createProgressCallback(ctx);
156:     const runtimeConfig = {
157:       ...DEFAULT_CONFIG,
158:       governorMode,
159:       maxTurnGap,
160:       periodicInterval,
161:       stateSupersessionGuard,
162:     };
163: 
164:     turnState.deliberation = runDeliberation(runtimeConfig, event.messages, ctx, logger, onProgress, turnsSinceLastAudit, lastExtractedContext !== null);
165: 
166:     try {
167:       const result = await turnState.deliberation;
168: 
169:       if (result.skippedByGovernor) {
170:         turnState.deliberation = null;
171:         lastExtractedContext = result.extractedContext ?? null;
172:         turnsSinceLastAudit++;
173:         if (result.extractedContext) {
174:           logger?.logExtraction(result.extractedContext);
175:         }
176:         logger?.log({
177:           type: "injection_skipped",
178:           reason: result.governorReason || "SKIPPED_BY_GOVERNOR",
179:           probe_count: 0,
180:           extractedContext: result.extractedContext,
181:         });
182:         if (ctx.hasUI) {
183:           ctx.ui.setStatus("consortium", "consortium: ⏭ skipped");
184:           ctx.ui.notify(formatVisibleMessage(result), "info");
185:         }
186:         return;
187:       }
188: 
189:       // Full probe audit ran — reset turn counter gap
190:       turnsSinceLastAudit = 0;
191: 
192:       if (result.synthesis.trim().startsWith("NO_CONTRIBUTION")) {
193:         turnState.deliberation = null;
194:         lastExtractedContext = result.extractedContext ?? null;
195:         if (result.extractedContext) {
196:           logger?.logExtraction(result.extractedContext);
197:         }
198:         logger?.log({
199:           type: "injection_skipped",
200:           reason: "NO_CONTRIBUTION",
201:           governor_reason: result.governorReason,
202:           probe_count: result.probes.length,
203:           extractedContext: result.extractedContext,
204:         });
205:         if (ctx.hasUI) {
206:           ctx.ui.setStatus("consortium", "consortium: ✓ complete (nothing to add)");
207:           ctx.ui.notify(formatVisibleMessage(result), "info");
208:         }
209:         return;
210:       }
211: 
212:       const syntheticMessage: AgentMessage = {
213:         role: "user",
214:         content: `[CONSORTIUM DELIBERATION]\n\n${result.synthesis}`,
215:         timestamp: Date.now(),
216:       };
217: 
218:       const messages = [...event.messages];
219:       messages.push(syntheticMessage);
220:       turnState.deliberation = null;
221:       lastExtractedContext = result.extractedContext ?? null;
222:       if (result.extractedContext) {
223:         logger?.logExtraction(result.extractedContext);
224:       }
225: 
226:       logger?.log({
227:         type: "injection_complete",
228:         synthesis_length: result.synthesis.length,
229:         probe_count: result.probes.length,
230:         errors: result.errors,
231:         governor_reason: result.governorReason,
232:         probes: result.probes,
233:         synthesis: result.synthesis,
234:         extractedContext: result.extractedContext,
235:       });
236: 
237:       // Persist in session JSONL
238:       try {
239:         pi.appendEntry(CUSTOM_TYPE, {
240:           schemaVersion: "0.1",
241:           kind: "deliberation",
242:           synthesis: result.synthesis,
243:           probe_count: result.probes.length,
244:           extractedContext: result.extractedContext,
245:           errors: result.errors,
246:         });
247:       } catch {
248:         // Some modes don't support session append.
249:       }
250: 
251:       // Visible TUI notification
252:       if (ctx.hasUI) {
253:         ctx.ui.notify(formatVisibleMessage(result), result.errors?.length ? "warning" : "info");
254:       }
255: 
256:       if (result.errors) {
257:         if (ctx.hasUI) {
258:           ctx.ui.setStatus("consortium", `consortium: ⚠ ${result.errors.length} error(s)`);
259:         }
260:       } else {
261:         if (ctx.hasUI) {
262:           ctx.ui.setStatus("consortium", "consortium: ✓ complete");
263:         }
264:       }
265: 
266:       return { messages };
267:     } catch (err) {
268:       const msg = err instanceof Error ? err.message : String(err);
269:       logger?.log({ type: "deliberation_failed", error: msg });
270:       if (ctx.hasUI) {
271:         ctx.ui.setStatus("consortium", `consortium: ✖ failed: ${msg}`);
272:       }
273:       turnState.deliberation = null;
274:       return;
275:     }
276:   });
