367: /** Resolve the deliberation model from CONSORTIUM_MODEL env var, falling back to ctx.model. */
368: function resolveDeliberationModel(
369:   ctx: ExtensionContext,
370: ): { provider: string; id: string; source: string } {
371:   const ref = parseModelRef(process.env.CONSORTIUM_MODEL);
372:   if (ref) {
373:     const model = ctx.modelRegistry.find(ref.provider, ref.modelId);
374:     if (model) {
375:       return { provider: model.provider, id: model.id, source: "CONSORTIUM_MODEL" };
376:     }
377:     // Env var set but model not found — log warning and fall through
378:     console.warn(`[consortium] CONSORTIUM_MODEL="${process.env.CONSORTIUM_MODEL}" resolved but not found in model registry — falling back to executor model`);
379:   }
380:   // Fallback to executor model
381:   if (!ctx.model) {
382:     throw new Error("No active model available from ctx.model and CONSORTIUM_MODEL not resolvable");
383:   }
384:   return { provider: ctx.model.provider, id: ctx.model.id, source: "ctx.model" };
385: }
