387: /** Run the full deliberation cycle. */
388: export async function runDeliberation(
389:   baseConfig: typeof DEFAULT_CONFIG,
390:   input: string | AgentMessage[],
391:   ctx: ExtensionContext,
392:   logger: ConsortiumLogger,
393:   onProgress: (phase: string, current: number, total: number, role?: string) => void,
394:   turnsSinceLastAudit: number,
395:   baselineAvailable: boolean,
396: ): Promise<DeliberationResult> {
397:   const deliberationModel = resolveDeliberationModel(ctx);
398:   const modelRegistry = ctx.modelRegistry;
399: 
400:   const config: ConsortiumConfig = {
401:     ...baseConfig,
402:     probes: baseConfig.probes.map((p) => ({
403:       ...p,
404:       provider: deliberationModel.provider,
405:       modelId: deliberationModel.id,
406:     })),
407:     synthesis: {
408:       ...baseConfig.synthesis,
409:       provider: deliberationModel.provider,
410:       modelId: deliberationModel.id,
411:     },
412:     extraction: baseConfig.extraction
413:       ? {
414:           ...baseConfig.extraction,
415:           provider: deliberationModel.provider,
416:           modelId: deliberationModel.id,
417:         }
418:       : undefined,
419:   };
420: 
421:   logger.log({
422:     type: "deliberation_start",
423:     model: `${deliberationModel.provider}/${deliberationModel.id}`,
424:     modelSource: deliberationModel.source,
425:     probe_count: config.probes.length,
426:   });
427: 
428:   // ── Telemetry state (local to this runDeliberation call) ──
429:   const acc = createUsageAccumulator();
430:   let baselineSupplied: boolean | undefined;
431:   const telemetryLog = (event: TelemetryEvent): void => {
432:     logger.log(event);
433:   };
434: 
435:   const onBaselineCheck = (bs: boolean): void => {
436:     baselineSupplied = bs;
437:     safeLog(telemetryLog, { type: "baseline_check", baseline_available: baselineAvailable, baseline_supplied: bs });
438:   };
439: 
440:   const callModel: ModelCallFn = async (modelKey, system, user, _maxTokens, _temperature, signal) => {
441:     const start = Date.now();
442:     const { provider, modelId, role } = resolveModelKey(modelKey, config);
443: 
444:     logger.log({
445:       type: "probe_start",
446:       modelKey,
447:       role: role ?? undefined,
448:       provider,
449:       modelId,
450:       system_prompt: system,
451:       user_input: user,
452:     });
453: 
454:     try {
455:       const result = await callModelWithAuth(provider, modelId, system, user, modelRegistry, signal);
456:       const duration = Date.now() - start;
457:       const usageReported = result.usage !== null;
458: 
459:       // Record usage in accumulator
460:       if (result.usage !== null) {
461:         acc.addReported(result.usage);
462:       } else {
463:         acc.addUnreported();
464:       }
465: 
466:       // Log probe_complete with usage_reported flag
467:       const logEntry: Record<string, unknown> = {
468:         type: "probe_complete",
469:         modelKey,
470:         role: role ?? undefined,
471:         duration_ms: duration,
472:         output_length: result.text.length,
473:         output: result.text,
474:         usage_reported: usageReported,
475:       };
476:       if (result.usage !== null) {
477:         logEntry.usage = result.usage;
478:       }
479:       logger.log(logEntry);
480: 
481:       return result.text;
482:     } catch (err) {
483:       const duration = Date.now() - start;
484:       const msg = err instanceof Error ? err.message : String(err);
485:       logger.log({ type: "probe_error", modelKey, duration_ms: duration, error: msg });
486:       throw err;
487:     }
488:   };
489: 
490:   const core = new ConsortiumCore(config, callModel, onBaselineCheck);
491:   const result = await core.deliberate(input, ctx.signal, onProgress, turnsSinceLastAudit);
492: 
493:   // ── Final deliberation_telemetry (after core completes) ──
494:   const finalEvent = buildDeliberationTelemetry(baselineAvailable, baselineSupplied, acc);
495:   safeLog(telemetryLog, finalEvent);
496: 
497:   return result;
498: }
