500: /** Resolve provider + modelId from a modelKey string. */
501: function resolveModelKey(
502:   modelKey: string,
503:   config: ConsortiumConfig,
504: ): { provider: string; modelId: string; role?: string } {
505:   if (modelKey === "synthesis") {
506:     return { provider: config.synthesis.provider, modelId: config.synthesis.modelId };
507:   }
508:   if (modelKey === "extraction") {
509:     if (config.extraction) {
510:       return { provider: config.extraction.provider, modelId: config.extraction.modelId };
511:     }
512:     return { provider: config.synthesis.provider, modelId: config.synthesis.modelId };
513:   }
514:   const match = modelKey.match(/^probe:(\d+)(?::(.+))?$/);
515:   if (match) {
516:     const i = parseInt(match[1], 10);
517:     const probe = config.probes[i];
518:     if (!probe) {
519:       throw new Error(`Probe ${i} not found in config`);
520:     }
521:     return { provider: probe.provider, modelId: probe.modelId, role: match[2] ?? probe.role };
522:   }
523:   throw new Error(`Unknown modelKey: "${modelKey}"`);
524: }

