1: // Governor decision module — decides whether full probe deliberation should run.
2: 
3: import type { ConsortiumConfig, ExtractedContext, GovernorMode } from "./types.js";
4: 
5: export interface GovernorDecision {
6:   /** True if full probe deliberation & synthesis should be executed. */
7:   shouldDeliberate: boolean;
8:   /** Human-readable reason explaining the decision. */
9:   reason: string;
10: }
11: 
12: /** Evaluate whether deliberation should run based on configuration, context, and turn state. */
13: export function hasExplicitDurableStateSupersession(currentUserTurn: string): boolean {
14:   const hasReplacementVerb = /\b(?:replace|replaces|replaced|replacing|supersede|supersedes|superseded|superseding|retire|retires|retired|retiring|migrate|migrates|migrated|migrating)\b/i.test(currentUserTurn);
15:   const hasDurableArtifact = /\bPROJECT_STATE\.md\b|\b[\w.-]+\.ya?ml\b/i.test(currentUserTurn);
16:   return hasReplacementVerb && hasDurableArtifact;
17: }
18: 
19: export function shouldDeliberate(
20:   config: ConsortiumConfig,
21:   extractedContext?: ExtractedContext,
22:   turnsSinceLastAudit: number = 0,
23:   currentUserTurn: string = "",
24: ): GovernorDecision {
25:   const mode: GovernorMode = config.governorMode ?? "smart_extractor";
26:   const maxTurnGap = config.maxTurnGap ?? 20;
27:   const periodicInterval = config.periodicInterval ?? 10;
28: 
29:   if (mode === "always") {
30:     return {
31:       shouldDeliberate: true,
32:       reason: "Mode is 'always' — full audit enabled on every turn",
33:     };
34:   }
35: 
36:   if (mode === "manual") {
37:     return {
38:       shouldDeliberate: false,
39:       reason: "Mode is 'manual' — skipped until explicitly triggered",
40:     };
41:   }
42: 
43:   if (mode === "periodic") {
44:     if (turnsSinceLastAudit >= periodicInterval) {
45:       return {
46:         shouldDeliberate: true,
47:         reason: `Periodic turn interval (${periodicInterval}) reached`,
48:       };
49:     }
50:     return {
51:       shouldDeliberate: false,
52:       reason: `Periodic turn interval (${periodicInterval}) not reached (${turnsSinceLastAudit}/${periodicInterval})`,
53:     };
54:   }
55: 
56:   // mode === "smart_extractor" (default)
57:   if (turnsSinceLastAudit >= maxTurnGap) {
58:     return {
59:       shouldDeliberate: true,
60:       reason: `Maximum turn gap (${maxTurnGap}) reached — forcing periodic safety audit`,
61:     };
62:   }
63: 
64:   if (config.stateSupersessionGuard === true && hasExplicitDurableStateSupersession(currentUserTurn)) {
65:     return {
66:       shouldDeliberate: true,
67:       reason: "Explicit durable-state supersession guard",
68:     };
69:   }
70: 
71:   if (extractedContext) {
72:     if (extractedContext.deliberationNeeded === false) {
73:       return {
74:         shouldDeliberate: false,
75:         reason: extractedContext.deliberationReason || "Context extraction determined full probe audit is not needed",
76:       };
77:     }
78:     if (extractedContext.deliberationNeeded === true) {
79:       return {
80:         shouldDeliberate: true,
81:         reason: extractedContext.deliberationReason || "Context extraction identified active gaps or unverified changes",
82:       };
83:     }
84:   }
85: 
86:   // Fallback default if extraction data is unavailable
87:   return {
88:     shouldDeliberate: true,
89:     reason: "No extraction signal available — defaulting to full audit for safety",
90:   };
91: }
