1: // ConsortiumCore — pure logic, no Pi dependency.
2: // Orchestrates divergence (parallel probes) and convergence (synthesis).
3: 
4: import type { ConsortiumConfig, DeliberationResult, ProbeResult, ProgressCallback, ExtractedContext } from "./types.js";
5: import type { AgentMessage } from "@earendil-works/pi-agent-core";
6: import { extractContextFromMessages, getDefaultExtractedContext } from "./extraction.js";
7: import { buildProbeInputXml } from "./context.js";
8: import { shouldDeliberate } from "./governor.js";
9: 
10: /** Injectable model call function (mockable for tests). */
11: export type ModelCallFn = (
12:   modelKey: string,
13:   system: string,
14:   user: string,
15:   maxTokens: number,
16:   temperature: number,
17:   signal: AbortSignal | undefined,
18: ) => Promise<string>;
19: 
20: /** Validate probe output — must start with NO_CONTRIBUTION or severity tag.
21:  * If the model ignored instructions and answered the user's question,
22:  * coerce to NO_CONTRIBUTION so it never reaches synthesis.
23:  *
24:  * Normalizes a leading "TAG " prefix (e.g. "TAG INFO x" → "INFO x")
25:  * before validation, recovering outputs where the model wrote the
26:  * placeholder literally. */
27: function validateProbeOutput(text: string): string {
28:   let trimmed = text.trim();
29:   // Strip leading "TAG " if followed by a recognized severity tag.
30:   if (trimmed.startsWith("TAG ") && /^(INFO|WARN|BLOCK)\s+\S/.test(trimmed.slice(4))) {
31:     trimmed = trimmed.slice(4);
32:   }
33:   // Also handle "TAG NO_CONTRIBUTION".
34:   if (trimmed === "TAG NO_CONTRIBUTION") {
35:     trimmed = "NO_CONTRIBUTION";
36:   }
37:   if (trimmed.startsWith("NO_CONTRIBUTION")) return trimmed;
38:   // Match severity tag followed by any non-whitespace (not just space).
39:   // Bare tags like "WARN\n" with no content are invalid.
40:   if (/^(INFO|WARN|BLOCK)\s+\S/.test(trimmed)) return trimmed;
41:   // Model ignored instructions or emitted bare tag — discard output
42:   return "NO_CONTRIBUTION";
43: }
44: 
45: export class ConsortiumCore {
46:   private lastExtractedContext?: ExtractedContext;
47: 
48:   constructor(
49:     private config: ConsortiumConfig,
50:     private callModel: ModelCallFn,
51:     private onBaselineCheck?: (baselineSupplied: boolean) => void,
52:   ) {}
53: 
54:   async deliberate(
55:     input: string | AgentMessage[],
56:     externalSignal?: AbortSignal,
57:     onProgress?: ProgressCallback,
58:     turnsSinceLastAudit: number = 0,
59:     previousContext?: ExtractedContext,
60:   ): Promise<DeliberationResult> {
61:     if (externalSignal?.aborted) {
62:       throw new Error("Deliberation aborted");
63:     }
64: 
65:     const masterController = new AbortController();
66:     if (externalSignal) {
67:       if (externalSignal.aborted) {
68:         masterController.abort();
69:       } else {
70:         externalSignal.addEventListener("abort", () => masterController.abort(), { once: true });
71:       }
72:     }
73: 
74:     const errors: string[] = [];
75:     const probeTotal = this.config.probes.length;
76: 
77:     // Phase 0.5 (Pre-check): Evaluate governor gate before extraction if context is not required (e.g. periodic or manual mode)
78:     const preGovernorDecision = shouldDeliberate(this.config, undefined, turnsSinceLastAudit);
79:     if (!preGovernorDecision.shouldDeliberate) {
80:       onProgress?.("complete", 0, 0);
81:       return {
82:         probes: [],
83:         synthesis: "NO_CONTRIBUTION",
84:         extractedContext: undefined,
85:         skippedByGovernor: true,
86:         governorReason: preGovernorDecision.reason,
87:         errors: errors.length > 0 ? errors : undefined,
88:       };
89:     }
90: 
91:     let userContext: string;
92:     let extractedContext: ExtractedContext | undefined;
93: 
94:     if (Array.isArray(input)) {
95:       // Phase 0: Extraction pass
96:       onProgress?.("extraction", 0, 1);
97:       try {
98:         const priorContext = previousContext ?? this.lastExtractedContext;
99:         const baselineSupplied = priorContext !== undefined;
100:         try { this.onBaselineCheck?.(baselineSupplied); } catch { /* isolated */ }
101:         extractedContext = await extractContextFromMessages(input, this.callModel, priorContext, masterController.signal);
102:         this.lastExtractedContext = extractedContext;
103:       } catch (err) {
104:         const msg = err instanceof Error ? err.message : String(err);
105:         errors.push(`Extraction: ${msg}`);
106:         extractedContext = getDefaultExtractedContext(input);
107:       }
108:       userContext = buildProbeInputXml(input, extractedContext);
109:     } else {
110:       userContext = input;
111:     }
112: 
113:     const currentUserMessage = Array.isArray(input)
114:       ? [...input].reverse().find((message) => message.role === "user" && "content" in message && typeof message.content === "string")
115:       : undefined;
116:     const currentUserTurn = currentUserMessage && "content" in currentUserMessage && typeof currentUserMessage.content === "string"
117:       ? currentUserMessage.content
118:       : "";
119: 
120:     // Phase 0.5 (Post-extraction): Re-evaluate governor gate with extracted context (e.g. for smart_extractor mode)
121:     const governorDecision = shouldDeliberate(this.config, extractedContext, turnsSinceLastAudit, currentUserTurn);
122:     if (!governorDecision.shouldDeliberate) {
123:       onProgress?.("complete", 0, 0);
124:       return {
125:         probes: [],
126:         synthesis: "NO_CONTRIBUTION",
127:         extractedContext,
128:         skippedByGovernor: true,
129:         governorReason: governorDecision.reason,
130:         errors: errors.length > 0 ? errors : undefined,
131:       };
132:     }
133: 
134:     // Phase 1: Divergence — parallel or serial probes
135:     const probeResults = await this.runProbes(userContext, masterController.signal, errors, onProgress, probeTotal);
136: 
137:     // Skip synthesis if all probes had nothing to contribute
138:     const allNoContribution = probeResults.every(
139:       (p) => p.text.trim().startsWith("NO_CONTRIBUTION"),
140:     );
141:     if (allNoContribution) {
142:       onProgress?.("complete", 0, 0);
143:       return {
144:         probes: probeResults,
145:         synthesis: "NO_CONTRIBUTION",
146:         extractedContext,
147:         governorReason: governorDecision.reason,
148:         errors: errors.length > 0 ? errors : undefined,
149:       };
150:     }
151: 
152:     // Phase 2: Convergence — synthesis
153:     onProgress?.("synthesis", 0, 1);
154:     const synthesisUser = this.formatProbeInputs(probeResults);
155:     const synthesis = await this.runSynthesis(synthesisUser, masterController.signal, errors);
156: 
157:     onProgress?.("complete", 0, 0);
158:     return {
159:       probes: probeResults,
160:       synthesis,
161:       extractedContext,
162:       governorReason: governorDecision.reason,
163:       errors: errors.length > 0 ? errors : undefined,
164:     };
165:   }
166: 
167:   private async runProbes(
168:     userContext: string,
169:     signal: AbortSignal,
170:     errors: string[],
171:     onProgress?: ProgressCallback,
172:     probeTotal?: number,
173:   ): Promise<ProbeResult[]> {
174:     const mode = this.config.executionMode ?? "serial";
175: 
176:     if (mode === "serial") {
177:       return this.runProbesSerial(userContext, signal, errors, onProgress, probeTotal);
178:     }
179: 
180:     return this.runProbesParallel(userContext, signal, errors, onProgress, probeTotal);
181:   }
182: 
183:   private async runProbesParallel(
184:     userContext: string,
185:     signal: AbortSignal,
186:     errors: string[],
187:     onProgress?: ProgressCallback,
188:     probeTotal?: number,
189:   ): Promise<ProbeResult[]> {
190:     let completed = 0;
191: 
192:     const probePromises = this.config.probes.map(async (probe, i) => {
193:       const probeController = new AbortController();
194:       const onMasterAbort = () => probeController.abort();
195:       signal.addEventListener("abort", onMasterAbort, { once: true });
196: 
197:       const timeoutId = setTimeout(() => probeController.abort(), this.config.probeTimeoutMs);
198: 
199:       try {
200:         const probeUser = probe.roleLens
201:           ? `${userContext}\n\n---\n\n${probe.roleLens}`
202:           : userContext;
203:         const result = await this.callModel(
204:           `probe:${i}:${probe.role}`,
205:           probe.systemPrompt,
206:           probeUser,
207:           this.config.maxProbeTokens,
208:           this.config.probeTemperature,
209:           probeController.signal,
210:         );
211:         const validated = validateProbeOutput(result);
212:         return { role: probe.role, text: validated };
213:       } catch (err) {
214:         const msg = err instanceof Error ? err.message : String(err);
215:         errors.push(`Probe "${probe.role}": ${msg}`);
216:         return { role: probe.role, text: `[error: ${msg}]` };
217:       } finally {
218:         clearTimeout(timeoutId);
219:         signal.removeEventListener("abort", onMasterAbort);
220:         completed++;
221:         onProgress?.("probe", completed, probeTotal ?? this.config.probes.length, probe.role);
222:       }
223:     });
224: 
225:     return Promise.all(probePromises);
226:   }
227: 
228:   private async runProbesSerial(
229:     userContext: string,
230:     signal: AbortSignal,
231:     errors: string[],
232:     onProgress?: ProgressCallback,
233:     probeTotal?: number,
234:   ): Promise<ProbeResult[]> {
235:     const results: ProbeResult[] = [];
236:     const total = probeTotal ?? this.config.probes.length;
237:     for (const [i, probe] of this.config.probes.entries()) {
238:       const probeController = new AbortController();
239:       const onMasterAbort = () => probeController.abort();
240:       signal.addEventListener("abort", onMasterAbort, { once: true });
241: 
242:       const timeoutId = setTimeout(() => probeController.abort(), this.config.probeTimeoutMs);
243: 
244:       try {
245:         const probeUser = probe.roleLens
246:           ? `${userContext}\n\n---\n\n${probe.roleLens}`
247:           : userContext;
248:         const result = await this.callModel(
249:           `probe:${i}:${probe.role}`,
250:           probe.systemPrompt,
251:           probeUser,
252:           this.config.maxProbeTokens,
253:           this.config.probeTemperature,
254:           probeController.signal,
255:         );
256:         const validated = validateProbeOutput(result);
257:         results.push({ role: probe.role, text: validated });
258:       } catch (err) {
259:         const msg = err instanceof Error ? err.message : String(err);
260:         errors.push(`Probe "${probe.role}": ${msg}`);
261:         results.push({ role: probe.role, text: `[error: ${msg}]` });
262:       } finally {
263:         clearTimeout(timeoutId);
264:         signal.removeEventListener("abort", onMasterAbort);
265:         onProgress?.("probe", i + 1, total, probe.role);
266:       }
267:     }
268:     return results;
269:   }
270: 
271:   private async runSynthesis(
272:     synthesisUser: string,
273:     signal: AbortSignal,
274:     errors: string[],
275:   ): Promise<string> {
276:     try {
277:       return await this.callModel(
278:         "synthesis",
279:         this.config.synthesis.systemPrompt,
280:         synthesisUser,
281:         this.config.maxSynthesisTokens,
282:         this.config.synthesisTemperature,
283:         signal,
284:       );
285:     } catch (err) {
286:       const msg = err instanceof Error ? err.message : String(err);
287:       errors.push(`Synthesis: ${msg}`);
288:       return `[Synthesis failed: ${msg}]. Raw probes follow.`;
289:     }
290:   }
291: 
292:   private formatProbeInputs(probes: ProbeResult[]): string {
293:     return probes
294:       .map((p) => `## ${p.role.toUpperCase()} PROBE\n${p.text}`)
295:       .join("\n\n---\n\n");
296:   }
297: 
298: }

