108: def continuity_passes(fixture: Dict[str, Any], final_text: str) -> bool:
109:     if fixture.get("kind") != "positive":
110:         return True
111:     lower = final_text.lower()
112:     current = all(marker.lower() in lower for marker in fixture.get("current_markers", []))
113:     historical = True
114:     for marker in fixture.get("historical_markers", []):
115:         needle = marker.lower()
116:         position = lower.find(needle)
117:         if position < 0:
118:             historical = False
119:             continue
120:         context = lower[max(0, position - 100): position + len(needle) + 100]
121:         if not any(word in context for word in ("supersed", "histor", "replac", "former", "previous", "retired", "migrated")):
122:             historical = False
123:     return current and historical
