135: def verify_review_session(expected_sha256: str) -> Dict[str, Any]:
136:     if not REVIEW_SESSION_PATH.is_file() or sha256_file(REVIEW_SESSION_PATH) != expected_sha256:
137:         raise RuntimeError("c03 review session evidence mismatch")
138:     events = [json.loads(line) for line in REVIEW_SESSION_PATH.read_text().splitlines() if line.strip()]
139:     model = next((event for event in events if event.get("type") == "model_change"), None)
140:     thinking = next((event for event in events if event.get("type") == "thinking_level_change"), None)
141:     info = next((event for event in events if event.get("type") == "session_info"), None)
142:     messages = [event for event in events if event.get("type") == "message" and event.get("message", {}).get("role") == "assistant"]
143:     final_text = "" if not messages else "".join(item.get("text", "") for item in messages[-1]["message"].get("content", []) if isinstance(item, dict))
144:     checks = {
145:         "session_name": isinstance(info, dict) and str(info.get("name", "")).startswith("c03-8081-twins"),
146:         "provider": isinstance(model, dict) and model.get("provider") == MODEL_PROVIDER,
147:         "model": isinstance(model, dict) and model.get("modelId") == MODEL_ID,
148:         "thinking": isinstance(thinking, dict) and thinking.get("thinkingLevel") == THINKING_LEVEL,
149:         "pass_verdict": re.search(r"(?:HEADLINE[^\n]*PASS|\*\*PASS\*\*)", final_text, re.IGNORECASE) is not None,
150:         "no_blocker": re.search(r"BLOCKER\s*:\s*(?:None|No\b)", final_text, re.IGNORECASE) is not None,
151:     }
152:     if not all(checks.values()):
153:         raise RuntimeError(f"c03 review session gate failed: {checks}")
154:     return {"checks": checks, "session_timestamp": events[0].get("timestamp"), "event_count": len(events)}
