180: def verify_contract(expected_sha256: str, freeze_commit: str) -> Dict[str, Any]:
181:     if sha256_file(CONTRACT_PATH) != expected_sha256:
182:         raise RuntimeError("c03 contract SHA-256 mismatch")
183:     data = json.loads(CONTRACT_PATH.read_text())
184:     if data.get("schema_version") != "c03-contract-files-v1" or not isinstance(data.get("files"), list):
185:         raise RuntimeError("c03 contract schema invalid")
186:     ancestor = subprocess.run(["git", "merge-base", "--is-ancestor", freeze_commit, "HEAD"], cwd=REPO_ROOT, check=False)
187:     if ancestor.returncode != 0:
188:         raise RuntimeError("c03 freeze commit is not an ancestor of HEAD")
189:     paths: set[str] = set()
190:     for item in data["files"]:
191:         if not isinstance(item, dict) or set(item) != {"path", "sha256"}:
192:             raise RuntimeError("c03 contract entry invalid")
193:         rel, expected = item["path"], item["sha256"]
194:         if not isinstance(rel, str) or rel in paths or rel.startswith("/") or ".." in Path(rel).parts:
195:             raise RuntimeError("c03 contract path invalid")
196:         paths.add(rel)
197:         target = REPO_ROOT / rel
198:         if not target.is_file() or sha256_file(target) != expected:
199:             raise RuntimeError(f"c03 current contract file mismatch: {rel}")
200:         frozen = subprocess.run(["git", "show", f"{freeze_commit}:{rel}"], cwd=REPO_ROOT, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
201:         if frozen.returncode != 0 or p.sha256_bytes(frozen.stdout) != expected:
202:             raise RuntimeError(f"c03 frozen contract file mismatch: {rel}")
203:     if not paths:
204:         raise RuntimeError("c03 contract has no files")
205:     return data
