208: class C03Sequencer:
209:     def __init__(self, prompts: List[str]) -> None:
210:         self.prompts = prompts
211:         self.responses: Dict[str, Dict[str, Any]] = {}
212:         self.prompts_sent = 0
213:         self.settles = 0
214:         self.final_queries = False
215:         self.complete = False
216:         self.errors: List[str] = []
217: 
218:     def on_event(self, event: Dict[str, Any]) -> List[Dict[str, Any]]:
219:         actions: List[Dict[str, Any]] = []
220:         if event.get("type") == "response" and event.get("id"):
221:             self.responses[str(event["id"])] = event
222:         if self.prompts_sent == 0 and {"get_state", "get_commands"}.issubset(self.responses):
223:             if all(self.responses[key].get("success") is True for key in ("get_state", "get_commands")):
224:                 actions.append({"id": "prompt_0", "type": "prompt", "message": self.prompts[0]})
225:                 self.prompts_sent = 1
226:             elif not self.errors:
227:                 self.errors.append("initial response unsuccessful")
228:         if event.get("type") == "agent_settled":
229:             if self.prompts_sent == 0 or self.settles >= self.prompts_sent:
230:                 self.errors.append("unexpected agent_settled ordering")
231:             else:
232:                 self.settles += 1
233:                 if self.settles < len(self.prompts):
234:                     index = self.settles
235:                     actions.append({"id": f"prompt_{index}", "type": "prompt", "message": self.prompts[index]})
236:                     self.prompts_sent += 1
237:                 elif not self.final_queries:
238:                     actions.extend([
239:                         {"id": "state_final", "type": "get_state"}, {"id": "entries_final", "type": "get_entries"},
240:                         {"id": "stats_final", "type": "get_session_stats"}, {"id": "text_final", "type": "get_last_assistant_text"},
241:                     ])
242:                     self.final_queries = True
243:         required = {"state_final", "entries_final", "stats_final", "text_final"}
244:         if self.final_queries and required.issubset(self.responses):
245:             self.complete = True
246:         return actions
