249: class C03Runner(p.Phase05Runner):
250:     def __init__(self, spec: Dict[str, Any], freeze_commit: str, runner_sha256: str, corpus_sha256: str, contract_sha256: str, review_session_sha256: str) -> None:
251:         super().__init__(spec["run_id"], spec["repetition"], "0" * 40, "0" * 40, "0" * 64, freeze_commit)
252:         self.spec = spec
253:         self.fixture = FIXTURES[spec["fixture_id"]]
254:         self.freeze_commit = freeze_commit
255:         self.expected_runner_sha = runner_sha256
256:         self.corpus_sha256 = corpus_sha256
257:         self.expected_contract_sha = contract_sha256
258:         self.review_session_sha256 = review_session_sha256
259:         self.tmp_root = Path("/tmp") / f"parcour-{self.run_id}"
260:         self.workspace = self.tmp_root / "workspace"
261:         self.sessions_dir = self.tmp_root / "sessions"
262:         self.runtime_root = self.tmp_root
263:         self.evidence_dir = REPO_ROOT / ".parcour-runs" / self.run_id
264:         self.fixture_before: Optional[Path] = None
265:         self.frozen_checks: Dict[str, bool] = {}
266: 
267:     def _validate_frozen_inputs(self) -> None:
268:         if self.spec != RUN_BY_ID.get(self.run_id):
269:             raise RuntimeError("c03 run ID does not match frozen schedule")
270:         for value, length, label in (
271:             (self.freeze_commit, 40, "freeze commit"), (self.expected_runner_sha, 64, "runner sha"),
272:             (self.corpus_sha256, 64, "corpus sha"), (self.expected_contract_sha, 64, "contract sha"),
273:             (self.review_session_sha256, 64, "review session sha"),
274:         ):
275:             if not re.fullmatch(rf"[0-9a-f]{{{length}}}", value):
276:                 raise RuntimeError(f"invalid {label}")
277:         contract = verify_contract(self.expected_contract_sha, self.freeze_commit)
278:         review = verify_review_session(self.review_session_sha256)
279:         freeze_timestamp = p.cmd_output(["git", "show", "-s", "--format=%cI", self.freeze_commit], cwd=REPO_ROOT)["output"].strip()
280:         preflight_timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()
281:         review_timing = review_timing_is_valid(freeze_timestamp, str(review.get("session_timestamp", "")), preflight_timestamp)
282:         if sha256_file(Path(__file__).resolve()) != self.expected_runner_sha:
283:             raise RuntimeError("c03 runner SHA mismatch")
284:         if sha256_file(CORPUS_PATH) != self.corpus_sha256:
285:             raise RuntimeError("c03 corpus SHA mismatch")
286:         pi = p.cmd_output(["pi", "--version"])
287:         node = p.cmd_output(["node", "--version"])
288:         command = build_pi_command(self.workspace, self.sessions_dir, self.run_id)
289:         child_env = build_child_env(dict(os.environ))
290:         self.frozen_checks = {
291:             "contract_nonempty": bool(contract.get("files")),
292:             "review_identity_and_verdict": all(review["checks"].values()),
293:             "review_after_freeze_before_preflight": review_timing,
294:             "pi_version": pi["exit_code"] == 0 and pi["output"].strip() == PI_VERSION,
295:             "node_version": node["exit_code"] == 0 and NODE_VERSION_PATTERN.fullmatch(node["output"].strip()) is not None,
296:             "executor_provider": command[command.index("--provider") + 1] == MODEL_PROVIDER,
297:             "executor_model": command[command.index("--model") + 1] == MODEL_ID,
298:             "executor_thinking": command[command.index("--thinking") + 1] == THINKING_LEVEL,
299:             "effective_consortium_model": child_env.get("CONSORTIUM_MODEL") == MODEL_REF,
300:             "extension_order": [command[index + 1] for index, value in enumerate(command) if value == "-e"] == [str(p.PROVIDER_EXT), str(p.CONSORTIUM_EXT), str(p.FOCUS_EXT)],
301:         }
302:         failed = [key for key, value in self.frozen_checks.items() if value is not True]
303:         if failed:
304:             raise RuntimeError(f"c03 frozen identity checks failed: {failed}")
305: 
306:     def _guard_existing_paths(self, all_targets: bool) -> None:
307:         specs = RUN_SPECS if all_targets else [self.spec]
