372:     def _run_rpc_loop(self, proc: subprocess.Popen, rpc_log_path: Path, stderr_path: Path) -> None:
373:         assert proc.stdin is not None and proc.stdout is not None
374:         buffer = b""
375:         total_start = time.monotonic()
376:         turn_start: Optional[float] = None
377:         sequencer = C03Sequencer(self.fixture["prompts"])
378:         reported_errors = 0
379:         self._send(proc, {"id": "get_state", "type": "get_state"})
380:         self._send(proc, {"id": "get_commands", "type": "get_commands"})
381:         with rpc_log_path.open("wb") as rpc_log:
382:             while not sequencer.complete:
383:                 if time.monotonic() - total_start > p.TIMEOUT_SECONDS * 3:
384:                     self.timeout_occurred = True; self.protocol_errors.append("Total timeout"); self._terminate_process_group(proc); break
385:                 if turn_start is not None and time.monotonic() - turn_start > p.TIMEOUT_SECONDS:
386:                     self.timeout_occurred = True; self.protocol_errors.append("Per-turn timeout"); self._terminate_process_group(proc); break
387:                 ready, _, _ = select.select([proc.stdout], [], [], 1.0)
388:                 if not ready:
389:                     if proc.poll() is not None: break
390:                     continue
391:                 chunk = os.read(proc.stdout.fileno(), 65536)
392:                 if not chunk: break
393:                 rpc_log.write(chunk); rpc_log.flush(); buffer += chunk
394:                 while b"\n" in buffer:
395:                     raw, buffer = buffer.split(b"\n", 1)
396:                     raw = raw[:-1] if raw.endswith(b"\r") else raw
397:                     if not raw: continue
398:                     text = raw.decode("utf-8", errors="replace"); self.raw_incoming.append(text)
399:                     try: event = json.loads(text)
400:                     except json.JSONDecodeError as exc: self.protocol_errors.append(f"Invalid JSON: {exc}"); continue
401:                     self.rpc_events.append(event); self._record_direction("out", event)
402:                     if event.get("type") == "response" and event.get("id"): self.responses[str(event["id"])] = event
403:                     actions = sequencer.on_event(event)
404:                     if len(sequencer.errors) > reported_errors:
405:                         self.protocol_errors.extend(sequencer.errors[reported_errors:]); reported_errors = len(sequencer.errors)
406:                     if sequencer.errors: break
407:                     if event.get("type") == "agent_settled": turn_start = None
408:                     for action in actions:
409:                         if action.get("type") == "prompt":
410:                             if action.get("id") == "prompt_0" and self.live_boundary_ts is None:
411:                                 self.live_boundary_ts = datetime.datetime.now(datetime.timezone.utc).isoformat()
412:                                 (self.tmp_root / "live-boundary.json").write_text(json.dumps({"run_id": self.run_id, "ts": self.live_boundary_ts}, indent=2) + "\n")
413:                             turn_start = time.monotonic()
414:                         self._send(proc, action)
415:                 if sequencer.errors: break
416:         if buffer.strip(): self.protocol_errors.append("Unterminated stdout bytes")
417:         if not sequencer.complete and not self.timeout_occurred and not sequencer.errors: self.protocol_errors.append("RPC stream ended before final responses")
418:         try: proc.stdin.close()
419:         except Exception: pass
420:         if proc.poll() is None:
421:             try: proc.wait(timeout=30)
422:             except subprocess.TimeoutExpired: self._terminate_process_group(proc)
423:         try: proc._stderr_handle.close()
424:         except Exception: pass
425:         if stderr_path.exists(): self.stderr_lines = stderr_path.read_text(errors="replace").splitlines()
426:         self.process_returncode = proc.returncode
