1684:     def _send(self, proc: subprocess.Popen, payload: Dict[str, Any]) -> None:
1685:         """Send and durably record one JSON-RPC command."""
1686:         assert proc.stdin is not None
1687:         line = json.dumps(payload, separators=(",", ":")).encode("utf-8") + b"\n"
1688:         proc.stdin.write(line)
1689:         proc.stdin.flush()
1690:         self.outgoing_commands.append(copy.deepcopy(payload))
1691:         record = {"ts": datetime.datetime.utcnow().isoformat() + "Z", "payload": copy.deepcopy(payload)}
1692:         self.outgoing_records.append(record)
1693:         self._record_direction("in", payload)
