1838:     def _collect_consortium_logs(self) -> None:
1839:         """Parse consortium JSONL sidecar logs with line annotation.
1840: 
1841:         Fix #11: annotate with consortium source file + 1-based line.
1842:         """
1843:         consortium_dir = self.workspace / ".pi" / "consortium"
1844:         if consortium_dir.exists():
1845:             logs = sorted(consortium_dir.glob("*.jsonl"))
1846:             if len(logs) != 1:
1847:                 self.protocol_errors.append(f"Expected 1 consortium JSONL, found {len(logs)}")
1848:             for log_file in logs:
1849:                 fname = log_file.name
1850:                 for line_num, line in enumerate(log_file.read_text().splitlines(), 1):
1851:                     line = line.strip()
1852:                     if line:
1853:                         try:
1854:                             ev = json.loads(line)
1855:                             ev["_source_file"] = fname
1856:                             ev["_source_line"] = line_num
1857:                             self.consortium_events.append(ev)
1858:                         except json.JSONDecodeError as exc:
1859:                             self.protocol_errors.append(f"Invalid consortium JSONL {fname}:{line_num}: {exc}")
